def run_engine(engine, broker, *, should_stop) -> None:
    """Startup, loop, shutdown. A start that fails before the engine took
    over order recovery only disconnects: the order-cancelling shutdown
    path is reserved for an engine that actually took over."""
    try:
        engine.startup()
    except BaseException:
        if getattr(engine, "took_over", False):
            engine.shutdown()
        else:
            try:
                broker.disconnect()
            except Exception:  # pragma: no cover - best effort
                log.exception("disconnect after failed startup")
        raise
    try:
        while not should_stop():
            broker.pump(1.0)
            engine.process_protection_priority()
            engine.tick()
    finally:
        engine.shutdown()

